-- كتالوغ أدوية «طمّني»
-- المصدر: قائمة أسعار الأدوية السورية 3-12-2023 + أشهر الأدوية المستوردة
--
-- name_ar: نقل صوتي مولّد آلياً لتسهيل البحث بالعربية.
--          ليس ترجمة طبية وليس مرجعاً دوائياً. فحص الحساسية لا يعتمد عليه،
--          بل على المواد الفعّالة (جدولا ingredients و catalog_ingredients
--          يُبنيان تلقائياً من active_ingredient عند تشغيل الخادم).
--
-- قاعدة بيانات قديمة بلا name_ar؟ لا تُعد الاستيراد: الخادم يملأ العمود
-- من هذا الملف تلقائياً عند التشغيل (server/catalogData.js).

ALTER TABLE medicines_catalog ADD COLUMN IF NOT EXISTS brand_name TEXT;
ALTER TABLE medicines_catalog ADD COLUMN IF NOT EXISTS name_ar TEXT;
ALTER TABLE medicines_catalog ADD COLUMN IF NOT EXISTS active_ingredient TEXT;
ALTER TABLE medicines_catalog ADD COLUMN IF NOT EXISTS strength TEXT;
ALTER TABLE medicines_catalog ADD COLUMN IF NOT EXISTS form TEXT;
ALTER TABLE medicines_catalog ADD COLUMN IF NOT EXISTS manufacturer TEXT;

